// Helper function to count occurrences of a character in a string
function countChar(s: string, c: char): int
    requires s != null
    ensures 0 <= countChar(s, c) <= s.Length
{
    var count := 0;
    var i := 0;
    while i < s.Length
        invariant 0 <= i <= s.Length
        invariant count == Count(c, s[0..i])
    {
        if s[i] == c {
            count := count + 1;
        }
        i := i + 1;
    }
    return count;
}

